import{_ as t,o as a,c as e,a5 as o}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"toLocaleString","description":"toLocaleString 方法详解 toLocaleString() 是 JavaScript 中用于将数字（或日期）格式化为本地化字符串的方法，支持自定义小数位数、千分位分隔符等。当你传入 minimumFractionDigits 和 maximumFractionDig。","frontmatter":{"title":"toLocaleString","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","实战与性能"],"description":"toLocaleString 方法详解 toLocaleString() 是 JavaScript 中用于将数字（或日期）格式化为本地化字符串的方法，支持自定义小数位数、千分位分隔符等。当你传入 minimumFractionDigits 和 maximumFractionDig。","sidebarWeight":40,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/需求实现/toLocaleString.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/08-实战与性能/toLocaleString.md","filePath":"posts/JavaScript系统教程/08-实战与性能/toLocaleString.md"}'),r={name:"posts/JavaScript系统教程/08-实战与性能/toLocaleString.md"};function c(n,i,l,s,p,m){return a(),e("div",null,[...i[0]||(i[0]=[o('<div><h1 id="tolocalestring" tabindex="-1">toLocaleString <a class="header-anchor" href="#tolocalestring" aria-label="Permalink to &quot;toLocaleString&quot;">​</a></h1><blockquote><p>本节目标：理解“toLocaleString”的核心思路，并能把它用于实际开发或面试表达。 ==toLocaleString== 方法详解 ==toLocaleString()== 是 JavaScript 中用于将数字（或日期）格式化为本地化字符串的方法，支持自定义小数位数、千分位分隔符等。当你传入 ==minimumFractionDigits== 和 ==maximumFractionDigits== 参数时，可以精确控制小数部分的显示格式。</p></blockquote><p>语法 javascript 复制 下载 number.toLocaleString([locales [, options]]);</p><ul><li><p>==locales==（可选）：语言/地区代码（如 ==&#39;en-US&#39;==、==&#39;zh-CN&#39;==），默认使用运行时环境的本地设置（==undefined== 表示自动选择）。</p></li><li><p>==options==（可选）：配置对象，控制格式化细节（如小数位数、货币符号等）。 参数说明：小数位数控制 在你的代码中： javascript 复制 下载 n.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals,});</p></li><li><p>==minimumFractionDigits==：强制保留的最小小数位数（不足补零）。</p></li><li><p>==maximumFractionDigits==：允许保留的最大小数位数（多余部分四舍五入）。</p></li><li><p>==decimals==：传入的变量，表示小数位数（如 ==2== 表示保留两位小数）。 关键特性</p></li><li><p>自动本地化适配</p></li><li><p>会根据用户设备的语言/地区自动选择格式（如千分位分隔符用逗号还是空格）。</p></li><li><p>示例（==en-US== vs ==de-DE==）：javascript复制下载(1234.5).toLocaleString(&#39;en-US&#39;); // &quot;1,234.5&quot; (1234.5).toLocaleString(&#39;de-DE&#39;); // &quot;1.234,5&quot;</p></li><li><p>小数位数处理</p></li><li><p>若 ==minimumFractionDigits = maximumFractionDigits==，则严格固定小数位数（补零或截断）。</p></li><li><p>示例（保留 2 位小数）：javascript复制下载(10).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); // &quot;10.00&quot;（补零）(10.456).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); // &quot;10.46&quot;（四舍五入）</p></li><li><p>其他常用 ==options==</p></li><li><p>==style==：格式类型（如 ==&#39;currency&#39;== 显示货币符号）。</p></li><li><p>==currency==：货币代码（如 ==&#39;USD&#39;==）。</p></li><li><p>==useGrouping==：是否使用千分位分隔符（默认为 ==true==）。javascript复制下载(1234.5).toLocaleString(&#39;en-US&#39;, { style: &#39;currency&#39;, currency: &#39;USD&#39; }); // &quot;$1,234.50&quot; 使用场景</p></li><li><p>显示金额/数量javascript复制下载const price = 1234.5;price.toLocaleString(&#39;zh-CN&#39;, { style: &#39;currency&#39;, currency: &#39;CNY&#39; }); // &quot;¥1,234.50&quot;</p></li><li><p>统一小数位数（如表格数据）javascript复制下载const numbers = [1, 1.2, 1.234];numbers.map(n =&gt; n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }));// [&quot;1.00&quot;, &quot;1.20&quot;, &quot;1.23&quot;]</p></li><li><p>国际化适配javascript复制下载// 根据用户浏览器语言自动选择格式userCount.toLocaleString(undefined, { minimumFractionDigits: 0 }); 注意事项</p></li><li><p>性能：频繁调用可能影响性能（尤其在大量数据循环中）。</p></li><li><p>一致性：若未指定 ==locales==，不同用户的显示结果可能不同。</p></li><li><p>浏览器兼容性：绝大多数现代浏览器支持，但在旧版 IE 中需谨慎使用。 总结</p></li><li><p>用途：本地化数字格式化，尤其适合金额、数量等场景。</p></li><li><p>核心参数：通过 ==minimumFractionDigits== 和 ==maximumFractionDigits== 精确控制小数位数。</p></li><li><p>扩展性：结合 ==style: &#39;currency&#39;== 可轻松实现货币格式化。</p></li></ul><p>示例代码： javascript 复制 下载 const formatNumber = (num, decimals = 2) =&gt; { return num.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals, });}; formatNumber(1234.567); // &quot;1,234.57&quot;（默认保留2位小数） &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28</a>&gt; &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/b75a0d7c-399b-41a3-9de9-567fc7280f28</a>&gt;</p></div>',1)])])}const d=t(r,[["render",c]]);export{g as __pageData,d as default};
